*** Begin Patch
*** Add File: output/styles.css
+:root {
+  --color-red: #c41e3a;
+  --color-red-600: #b61b35;
+  --color-navy: #1b3a5c;
+  --color-ink: #101828;
+  --color-muted: #475467;
+  --color-border: #e4e7ec;
+  --color-bg: #ffffff;
+  --color-surface: #ffffff;
+  --color-warm: #f9fafb;
+  --shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.06);
+  --shadow-md: 0 10px 20px rgba(16, 24, 40, 0.10);
+  --shadow-lg: 0 18px 40px rgba(16, 24, 40, 0.14);
+
+  --radius-sm: 10px;
+  --radius-md: 14px;
+  --radius-lg: 18px;
+
+  --container: 1120px;
+  --font-sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Inter,
+    Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  font-family: var(--font-sans);
+  color: var(--color-ink);
+  background: var(--color-bg);
+  line-height: 1.5;
+  text-rendering: optimizeLegibility;
+}
+
+img {
+  max-width: 100%;
+  display: block;
+}
+
+a {
+  color: inherit;
+}
+
+.skip-link {
+  position: absolute;
+  left: -999px;
+  top: 12px;
+  padding: 10px 12px;
+  border-radius: 10px;
+  background: var(--color-ink);
+  color: #fff;
+  z-index: 10000;
+}
+
+.skip-link:focus {
+  left: 12px;
+}
+
+.container {
+  width: min(var(--container), 100%);
+  margin: 0 auto;
+  padding: 0 18px;
+}
+
+.section {
+  padding: 64px 0;
+}
+
+.section--muted {
+  background: linear-gradient(180deg, var(--color-warm), #fff);
+}
+
+.kicker {
+  font-size: 12px;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--color-navy);
+  font-weight: 700;
+}
+
+.h1 {
+  font-size: clamp(34px, 4.6vw, 54px);
+  line-height: 1.06;
+  letter-spacing: -0.02em;
+}
+
+.h2 {
+  font-size: clamp(26px, 3vw, 36px);
+  line-height: 1.15;
+  letter-spacing: -0.01em;
+  margin: 0 0 12px;
+}
+
+.lead {
+  font-size: 18px;
+  color: var(--color-muted);
+  max-width: 64ch;
+}
+
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 10px;
+  border: 1px solid transparent;
+  background: transparent;
+  color: inherit;
+  font-weight: 700;
+  text-decoration: none;
+  padding: 12px 14px;
+  border-radius: 999px;
+  cursor: pointer;
+  transition: transform 0.12s ease, background 0.12s ease,
+    border-color 0.12s ease, box-shadow 0.12s ease;
+}
+
+.btn:focus-visible {
+  outline: 3px solid rgba(27, 58, 92, 0.28);
+  outline-offset: 3px;
+}
+
+.btn:hover {
+  transform: translateY(-1px);
+}
+
+.btn--primary {
+  background: var(--color-red);
+  color: #fff;
+  box-shadow: 0 10px 20px rgba(196, 30, 58, 0.25);
+}
+
+.btn--primary:hover {
+  background: var(--color-red-600);
+}
+
+.btn--secondary {
+  border-color: rgba(27, 58, 92, 0.22);
+  background: rgba(27, 58, 92, 0.06);
+  color: var(--color-navy);
+}
+
+.btn--ghost {
+  border-color: rgba(16, 24, 40, 0.14);
+  background: #fff;
+}
+
+.chip {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 8px 10px;
+  border-radius: 999px;
+  background: rgba(27, 58, 92, 0.06);
+  color: var(--color-navy);
+  border: 1px solid rgba(27, 58, 92, 0.14);
+  font-weight: 600;
+  font-size: 13px;
+}
+
+.card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-sm);
+}
+
+.card--hover {
+  transition: transform 0.18s ease, box-shadow 0.18s ease,
+    border-color 0.18s ease;
+}
+
+.card--hover:hover {
+  transform: translateY(-3px);
+  box-shadow: var(--shadow-md);
+  border-color: rgba(196, 30, 58, 0.22);
+}
+
+/* Header */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(255, 255, 255, 0.82);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid rgba(228, 231, 236, 0.9);
+}
+
+.utility-bar {
+  display: flex;
+  justify-content: flex-end;
+  gap: 12px;
+  padding: 8px 0;
+  font-size: 13px;
+  color: var(--color-muted);
+}
+
+.utility-bar a {
+  text-decoration: none;
+  padding: 4px 6px;
+  border-radius: 10px;
+}
+
+.utility-bar a:hover {
+  background: rgba(16, 24, 40, 0.05);
+}
+
+.nav-row {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 16px;
+  padding: 12px 0 14px;
+}
+
+.brand {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  text-decoration: none;
+}
+
+.brand-mark {
+  width: 38px;
+  height: 38px;
+  border-radius: 12px;
+  background: radial-gradient(
+      circle at 30% 30%,
+      rgba(255, 255, 255, 0.25),
+      transparent 55%
+    ),
+    linear-gradient(135deg, var(--color-red), var(--color-navy));
+  box-shadow: 0 12px 22px rgba(27, 58, 92, 0.18);
+}
+
+.brand-title {
+  font-weight: 900;
+  letter-spacing: -0.02em;
+}
+
+.brand-sub {
+  display: block;
+  font-weight: 600;
+  font-size: 12px;
+  color: var(--color-muted);
+  margin-top: 2px;
+}
+
+.desktop-nav {
+  display: none;
+  align-items: center;
+  gap: 8px;
+}
+
+.desktop-nav a {
+  text-decoration: none;
+  padding: 10px 10px;
+  border-radius: 999px;
+  font-weight: 650;
+  color: rgba(16, 24, 40, 0.86);
+}
+
+.desktop-nav a:hover,
+.desktop-nav a:focus-visible {
+  background: rgba(16, 24, 40, 0.05);
+}
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+}
+
+.menu-btn {
+  width: 42px;
+  height: 42px;
+  border-radius: 12px;
+  border: 1px solid rgba(16, 24, 40, 0.14);
+  background: #fff;
+}
+
+.menu-btn svg {
+  width: 20px;
+  height: 20px;
+}
+
+/* Mobile drawer */
+.drawer-overlay {
+  position: fixed;
+  inset: 0;
+  background: rgba(16, 24, 40, 0.55);
+  opacity: 0;
+  pointer-events: none;
+  transition: opacity 0.2s ease;
+  z-index: 80;
+}
+
+.drawer {
+  position: fixed;
+  inset: 0 0 0 auto;
+  width: min(360px, 88vw);
+  transform: translateX(110%);
+  transition: transform 0.22s ease;
+  background: #fff;
+  z-index: 90;
+  display: flex;
+  flex-direction: column;
+}
+
+.drawer header {
+  padding: 16px;
+  border-bottom: 1px solid var(--color-border);
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+}
+
+.drawer nav {
+  padding: 12px;
+  display: grid;
+  gap: 6px;
+}
+
+.drawer nav a {
+  text-decoration: none;
+  padding: 12px 12px;
+  border-radius: 14px;
+  font-weight: 650;
+  color: rgba(16, 24, 40, 0.9);
+  border: 1px solid rgba(228, 231, 236, 0.9);
+}
+
+.drawer nav a:hover {
+  background: rgba(16, 24, 40, 0.05);
+}
+
+.drawer footer {
+  margin-top: auto;
+  padding: 12px 16px 16px;
+  border-top: 1px solid var(--color-border);
+  display: grid;
+  gap: 10px;
+}
+
+body[data-drawer-open="true"] .drawer-overlay {
+  opacity: 1;
+  pointer-events: auto;
+}
+
+body[data-drawer-open="true"] .drawer {
+  transform: translateX(0%);
+}
+
+/* Hero */
+.hero {
+  padding: 54px 0 38px;
+}
+
+.hero-grid {
+  display: grid;
+  gap: 22px;
+}
+
+.hero-card {
+  border-radius: 24px;
+  overflow: hidden;
+  border: 1px solid rgba(228, 231, 236, 0.9);
+  background: linear-gradient(
+      180deg,
+      rgba(196, 30, 58, 0.07),
+      rgba(27, 58, 92, 0.05)
+    ),
+    #fff;
+  box-shadow: var(--shadow-lg);
+}
+
+.hero-inner {
+  padding: 26px;
+  display: grid;
+  gap: 22px;
+}
+
+.hero-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+  margin-top: 8px;
+}
+
+.hero-media {
+  position: relative;
+  min-height: 260px;
+}
+
+.hero-media img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+}
+
+.hero-media::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(
+    90deg,
+    rgba(255, 255, 255, 0.92),
+    rgba(255, 255, 255, 0) 58%
+  );
+}
+
+.hero-badges {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+/* Mission */
+.mission-grid {
+  display: grid;
+  gap: 18px;
+}
+
+.mission-copy {
+  padding: 22px;
+}
+
+.mission-aside {
+  padding: 22px;
+  border-left: 4px solid rgba(196, 30, 58, 0.18);
+}
+
+.mission-aside ul {
+  margin: 10px 0 0;
+  padding-left: 18px;
+  color: var(--color-muted);
+}
+
+/* Impact stats */
+.stats-grid {
+  display: grid;
+  gap: 14px;
+}
+
+.stat {
+  padding: 18px;
+  display: grid;
+  gap: 4px;
+}
+
+.stat .value {
+  font-size: 34px;
+  letter-spacing: -0.02em;
+  font-weight: 900;
+  color: var(--color-ink);
+}
+
+.stat .value strong {
+  color: var(--color-red);
+}
+
+.stat .label {
+  color: var(--color-muted);
+  font-weight: 650;
+}
+
+/* Programs */
+.accordion {
+  display: grid;
+  gap: 10px;
+}
+
+.acc-item {
+  overflow: hidden;
+}
+
+.acc-trigger {
+  width: 100%;
+  text-align: left;
+  background: #fff;
+  border: none;
+  cursor: pointer;
+  padding: 18px 18px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  font-weight: 850;
+  font-size: 16px;
+}
+
+.acc-trigger span {
+  color: rgba(16, 24, 40, 0.92);
+}
+
+.acc-trigger .meta {
+  font-size: 13px;
+  font-weight: 700;
+  color: var(--color-navy);
+  padding: 6px 10px;
+  border-radius: 999px;
+  border: 1px solid rgba(27, 58, 92, 0.18);
+  background: rgba(27, 58, 92, 0.05);
+}
+
+.acc-chevron {
+  transition: transform 0.18s ease;
+  flex: 0 0 auto;
+}
+
+.acc-panel {
+  height: 0;
+  overflow: hidden;
+  transition: height 0.22s ease;
+}
+
+.acc-panel-inner {
+  padding: 0 18px 18px;
+  color: var(--color-muted);
+}
+
+.acc-panel-inner a {
+  font-weight: 750;
+  color: var(--color-navy);
+  text-decoration: none;
+}
+
+.acc-panel-inner a:hover {
+  text-decoration: underline;
+}
+
+.acc-item[data-open="true"] .acc-chevron {
+  transform: rotate(180deg);
+}
+
+/* Get involved */
+.involved-grid {
+  display: grid;
+  gap: 14px;
+}
+
+.involved-card {
+  padding: 20px;
+  display: grid;
+  gap: 10px;
+}
+
+.involved-card h3 {
+  margin: 0;
+  font-size: 18px;
+  letter-spacing: -0.01em;
+}
+
+.involved-card p {
+  margin: 0;
+  color: var(--color-muted);
+}
+
+/* News */
+.news-header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 14px;
+  margin-bottom: 16px;
+}
+
+.carousel {
+  position: relative;
+}
+
+.carousel-window {
+  overflow: hidden;
+  border-radius: var(--radius-lg);
+}
+
+.carousel-track {
+  display: grid;
+  grid-auto-flow: column;
+  grid-auto-columns: 100%;
+  transition: transform 0.28s ease;
+}
+
+.news-card {
+  padding: 20px;
+  min-height: 100%;
+  display: grid;
+  gap: 12px;
+}
+
+.news-card h3 {
+  margin: 0;
+  font-size: 18px;
+  letter-spacing: -0.01em;
+}
+
+.news-card p {
+  margin: 0;
+  color: var(--color-muted);
+}
+
+.news-card .tag {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  font-weight: 700;
+  font-size: 13px;
+  color: var(--color-navy);
+}
+
+.carousel-controls {
+  display: flex;
+  gap: 10px;
+}
+
+.icon-btn {
+  width: 44px;
+  height: 44px;
+  border-radius: 14px;
+  border: 1px solid rgba(16, 24, 40, 0.14);
+  background: #fff;
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  cursor: pointer;
+  transition: transform 0.12s ease, background 0.12s ease;
+}
+
+.icon-btn:hover {
+  transform: translateY(-1px);
+  background: rgba(16, 24, 40, 0.04);
+}
+
+.icon-btn:focus-visible {
+  outline: 3px solid rgba(27, 58, 92, 0.28);
+  outline-offset: 3px;
+}
+
+/* Donate CTA */
+.donate-grid {
+  display: grid;
+  gap: 16px;
+  align-items: start;
+}
+
+.donate-copy {
+  padding: 22px;
+}
+
+.donate-table {
+  width: 100%;
+  border-collapse: collapse;
+  overflow: hidden;
+  border-radius: 14px;
+  border: 1px solid var(--color-border);
+}
+
+.donate-table th,
+.donate-table td {
+  text-align: left;
+  padding: 12px 12px;
+  border-bottom: 1px solid var(--color-border);
+  font-size: 14px;
+}
+
+.donate-table th {
+  background: rgba(27, 58, 92, 0.05);
+  color: rgba(16, 24, 40, 0.84);
+}
+
+.donate-table tr:last-child td {
+  border-bottom: none;
+}
+
+/* Footer */
+.site-footer {
+  padding: 48px 0;
+  border-top: 1px solid var(--color-border);
+  background: rgba(27, 58, 92, 0.03);
+}
+
+.footer-grid {
+  display: grid;
+  gap: 16px;
+}
+
+.footer-col {
+  padding: 18px;
+}
+
+.footer-col h3 {
+  margin: 0 0 10px;
+  font-size: 14px;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+  color: rgba(16, 24, 40, 0.78);
+}
+
+.footer-col a {
+  display: inline-block;
+  margin: 6px 0;
+  color: var(--color-muted);
+  text-decoration: none;
+  font-weight: 650;
+}
+
+.footer-col a:hover {
+  color: var(--color-ink);
+  text-decoration: underline;
+}
+
+.footer-bottom {
+  margin-top: 14px;
+  color: var(--color-muted);
+  font-size: 13px;
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+}
+
+.social {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.divider {
+  height: 1px;
+  background: rgba(228, 231, 236, 0.9);
+  margin: 10px 0 0;
+}
+
+/* Modal */
+.modal-overlay {
+  position: fixed;
+  inset: 0;
+  display: grid;
+  place-items: center;
+  background: rgba(16, 24, 40, 0.62);
+  opacity: 0;
+  pointer-events: none;
+  transition: opacity 0.18s ease;
+  z-index: 120;
+  padding: 18px;
+}
+
+.modal {
+  width: min(640px, 100%);
+  background: #fff;
+  border: 1px solid rgba(228, 231, 236, 0.9);
+  border-radius: 22px;
+  box-shadow: var(--shadow-lg);
+  transform: translateY(10px);
+  transition: transform 0.18s ease;
+}
+
+.modal header {
+  padding: 18px 18px 12px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 14px;
+  border-bottom: 1px solid var(--color-border);
+}
+
+.modal header h2 {
+  margin: 0;
+  font-size: 18px;
+  letter-spacing: -0.01em;
+}
+
+.modal .content {
+  padding: 16px 18px 18px;
+  display: grid;
+  gap: 14px;
+}
+
+.amounts {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 10px;
+}
+
+.amount-btn {
+  border-radius: 14px;
+  border: 1px solid rgba(16, 24, 40, 0.14);
+  background: #fff;
+  font-weight: 850;
+  padding: 12px 12px;
+  cursor: pointer;
+  transition: transform 0.12s ease, background 0.12s ease,
+    border-color 0.12s ease;
+}
+
+.amount-btn:hover {
+  transform: translateY(-1px);
+  background: rgba(196, 30, 58, 0.06);
+  border-color: rgba(196, 30, 58, 0.24);
+}
+
+.amount-btn[aria-pressed="true"] {
+  background: rgba(196, 30, 58, 0.12);
+  border-color: rgba(196, 30, 58, 0.38);
+}
+
+.donate-form {
+  display: grid;
+  gap: 12px;
+}
+
+.field {
+  display: grid;
+  gap: 6px;
+}
+
+.field label {
+  font-weight: 750;
+  font-size: 14px;
+}
+
+.field input,
+.field select {
+  padding: 12px 12px;
+  border-radius: 12px;
+  border: 1px solid rgba(16, 24, 40, 0.16);
+  font: inherit;
+}
+
+.field input:focus,
+.field select:focus {
+  outline: 3px solid rgba(196, 30, 58, 0.18);
+  border-color: rgba(196, 30, 58, 0.46);
+}
+
+.form-row {
+  display: grid;
+  gap: 10px;
+}
+
+.fineprint {
+  font-size: 13px;
+  color: var(--color-muted);
+}
+
+body[data-modal-open="true"] .modal-overlay {
+  opacity: 1;
+  pointer-events: auto;
+}
+
+body[data-modal-open="true"] .modal {
+  transform: translateY(0);
+}
+
+/* Responsive */
+@media (min-width: 760px) {
+  .desktop-nav {
+    display: flex;
+  }
+
+  .menu-btn {
+    display: none;
+  }
+
+  .hero-grid {
+    grid-template-columns: 1.12fr 0.88fr;
+    align-items: stretch;
+  }
+
+  .hero-media {
+    min-height: 100%;
+  }
+
+  .mission-grid {
+    grid-template-columns: 1.25fr 0.75fr;
+    align-items: start;
+  }
+
+  .stats-grid {
+    grid-template-columns: repeat(4, 1fr);
+  }
+
+  .involved-grid {
+    grid-template-columns: repeat(3, 1fr);
+  }
+
+  .donate-grid {
+    grid-template-columns: 1fr 1fr;
+  }
+
+  .footer-grid {
+    grid-template-columns: repeat(4, 1fr);
+  }
+
+  .carousel-track {
+    grid-auto-columns: 50%;
+  }
+}
+
+@media (min-width: 1020px) {
+  .carousel-track {
+    grid-auto-columns: 33.3333%;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  html {
+    scroll-behavior: auto;
+  }
+
+  * {
+    transition: none !important;
+    animation: none !important;
+  }
+}
+
*** End Patch
PATCH

